/**
 * The model kit's contract with render and ui (DESIGN §15). Everything is generated by code (SDF sculpting →
 * meshes); nothing is loaded from files. Models face +Z with their feet at the origin; 1 unit = 1 m.
 *
 * - Characters (players, クロヅメ animals, decoys, menu turntables) are skinned meshes posed procedurally.
 * - Antiques have a model each (weapons, shield, deployables, passive emblems) with a muzzle/tip anchor.
 * - Foes in crowds are rigid parts posed per instance (the renderer draws each part with an InstancedMesh).
 * - Bosses are single full models.
 */
import type * as THREE from 'three'
import type { FoeAttack, FoeKind } from '../data/enemies'
import type { ItemId } from '../data/items'
import type { SpeciesId } from '../data/species'
import type { FoeState, HandAct, MoveState, PropKind, ShotKind } from '../sim/types'

export type Quality = 'low' | 'medium' | 'high'

export interface HandPose {
  item: ItemId | null
  act: HandAct
  /** 0..1 charge / zoom / lock / guard raise. */
  charge: number
  /** Increments on every use; a change triggers recoil or a swing. */
  uses: number
  /** Combo step of the latest swing. */
  combo: number
  /** 0 = ready, 0..1 while the antique dissolves and re-forms. */
  swap: number
}

export type Emote = 'victory' | 'defeat' | 'cheer' | 'salute' | 'wave'

export interface CharacterPose {
  /** Horizontal velocity in the body frame: [right, forward] m/s (body yaw is the root's rotation.y). */
  localVel: [number, number]
  grounded: boolean
  /** Vertical velocity (m/s). */
  vy: number
  move: MoveState
  /** Aim relative to the body: yaw offset (rad, + = left) and pitch (+ = up). */
  aimYaw: number
  aimPitch: number
  hands: [HandPose, HandPose]
  state: 'alive' | 'down' | 'away'
  /** 0..1 while being revived. */
  revive: number
  /** True while kneeling to revive an ally. */
  reviving: boolean
  /** One-shot hurt flinch: increments on every hit taken. */
  hurt: number
  emote?: Emote
}

export interface CharacterModel {
  readonly root: THREE.Group
  readonly species: SpeciesId
  /** Advances the procedural animation (call once per rendered frame). */
  update(dt: number, pose: CharacterPose): void
  /** World-space muzzle / blade tip of the antique in paw 0 (right) or 1 (left). */
  muzzle(hand: 0 | 1, out: THREE.Vector3): THREE.Vector3
  /** World-space point just above the head (name tags, markers). */
  headTop(out: THREE.Vector3): THREE.Vector3
  /** Team colour of the armour trim and its pattern (0 stripes, 1 dots, 2 chevrons); null = ARK default. */
  setTeam(color: number | null, pattern: 0 | 1 | 2 | null): void
  /** 'kurozume': charcoal armour with a red claw-mark scarf. */
  setLook(look: 'ark' | 'kurozume'): void
  /** Visible passive gear (turtle shell, quills, glider membrane, jelly bubble…); dimmed when offline. */
  setPassives(passives: ItemId[], online: boolean): void
  /** 0..1 camouflage shimmer (1 = nearly invisible). */
  setCloak(amount: number): void
  /** 0..1 white hit flash. */
  setFlash(amount: number): void
  /** 0..1 remaining anima: brightness of the chest core. */
  setAnima(fraction: number): void
  /** Hologram look for decoys (translucent, scanlines). */
  setHologram(on: boolean): void
  dispose(): void
}

export interface ItemModel {
  readonly root: THREE.Group
  readonly id: ItemId
  /** Muzzle / blade tip in root space. */
  readonly muzzle: THREE.Vector3
  /** Animates charge/act details (hippo mouth, eel crackle, puffer inflate…). */
  update(dt: number, act: HandAct, charge: number): void
  dispose(): void
}

export interface FoeAnim {
  state: FoeState
  /** Seconds in the state. */
  st: number
  /** Global time (idle cycles). */
  time: number
  /** Horizontal speed (m/s) for gait cycles. */
  speed: number
  /** Stable per-foe random 0..1 (phase offsets, tint jitter). */
  seed: number
  hpFrac: number
  attack?: FoeAttack
  parts?: number[]
}

/** A crowd foe as rigid parts; the renderer draws each part with one InstancedMesh. */
export interface FoeRig {
  readonly kind: FoeKind
  readonly parts: readonly { name: string; geometry: THREE.BufferGeometry; material: THREE.Material }[]
  /** Writes each part's matrix relative to the foe's root (feet at origin, facing +Z). */
  pose(anim: FoeAnim, out: THREE.Matrix4[]): void
}

export interface BossModel {
  readonly root: THREE.Group
  readonly kind: FoeKind
  update(dt: number, anim: FoeAnim): void
  /** World-space weak point (core) for markers. */
  weakPoint(out: THREE.Vector3): THREE.Vector3
  dispose(): void
}

export interface PropModel {
  readonly root: THREE.Group
  readonly kind: PropKind
  /** `state` and `life` as in PropView. */
  update(dt: number, t: number, state: number, life: number | undefined): void
  /** 0..1 health for props with hp (lighthouse, hermit wall, nodes, cart): cracks, flicker. */
  setHealth?(fraction: number): void
  dispose(): void
}

/** Geometry + material for an instanced projectile kind (facing +Z, unit scale). */
export interface ShotLook {
  geometry: THREE.BufferGeometry
  material: THREE.Material
  /** Length scale along +Z at full speed (streaks). */
  stretch: number
}

export interface PrepareRequest {
  species?: readonly SpeciesId[]
  items?: readonly ItemId[]
  foes?: readonly FoeKind[]
  props?: readonly PropKind[]
}

export interface ModelKit {
  /** Generates (and caches) everything requested; progress 0..1. Safe to call repeatedly. */
  prepare(request: PrepareRequest, onProgress?: (fraction: number) => void): Promise<void>
  createCharacter(species: SpeciesId, options?: { look?: 'ark' | 'kurozume'; outline?: boolean }): CharacterModel
  /** Every antique has a model, passive ones included (emblems / gear). */
  createItem(item: ItemId): ItemModel
  foeRig(kind: FoeKind): FoeRig
  createBoss(kind: 'kuitsukushi' | 'goutetsu'): BossModel
  createProp(kind: PropKind): PropModel
  shotLook(kind: ShotKind): ShotLook
  dispose(): void
}
